// @pit: {"label": "Fetch Equibles income statements, latest earnings call, and FD news; cache to /tmp"}
async ({ eq: { financialStatement, earningsCall }, fd: { news }, workspace: { edit } }) => {
  const jobs: Record<string, () => Promise<any>> = {
    inc2026: () => financialStatement({ ticker: "NVDA", statement: "income", year: 2026, period: "FY" }),
    inc2025: () => financialStatement({ ticker: "NVDA", statement: "income", year: 2025, period: "FY" }),
    inc2024: () => financialStatement({ ticker: "NVDA", statement: "income", year: 2024, period: "FY" }),
    call: () => earningsCall({ ticker: "NVDA", fiscalYear: 2027, fiscalQuarter: 2, limit: 200 }),
    news: () => news({ ticker: "NVDA", limit: 20 }),
  };
  const keys = Object.keys(jobs);
  const res = await Promise.allSettled(keys.map((k) => jobs[k]()));
  const out: any = {};
  await Promise.all(keys.map(async (k, i) => {
    const r = res[i];
    const v = r.status === "fulfilled" ? r.value : { error: String(r.reason) };
    await edit(`/tmp/nvda/${k}.json`, { revision: null, changes: [{ kind: "replaceFile", content: JSON.stringify(v) }] });
    const s = JSON.stringify(v);
    out[k] = { len: s.length, url: v.url, count: v.count, meta: v.meta, error: v.error, preview: s.slice(0, 400) };
  }));
  return out;
}
